<?php
declare(strict_types=1);
header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');header('X-Content-Type-Options: nosniff');
function reply(array $data,int $status=200):never {http_response_code($status);echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);exit;}
function stop(int $s,string $m):never {reply(['error'=>$m],$s);}
$private=(getenv('AION_PRIVATE_DIR')?:dirname(__DIR__,2).'/aion2-private');define('DAEVA_OPERATIONS_CONTEXT',true);require __DIR__.'/operations-common.php';require __DIR__.'/billing-common.php';
function opsRate(string $key,int $cap,int $period):void {global $private;$p=$private.'/auth-limits/'.hash('sha256','operations:'.$key.($_SERVER['REMOTE_ADDR']??'').floor(time()/$period));$h=fopen($p,'c+');if(!$h)stop(503,'Servicio no disponible.');flock($h,LOCK_EX);$n=(int)stream_get_contents($h);if($n>=$cap){fclose($h);header('Retry-After: '.$period);stop(429,'Espera antes de reintentar.');}rewind($h);ftruncate($h,0);fwrite($h,(string)($n+1));fclose($h);}
$action=(string)($_GET['action']??'public');$method=$_SERVER['REQUEST_METHOD']??'';
try{
 $cfg=json_decode(file_get_contents($private.'/account-config.json'),true,32,JSON_THROW_ON_ERROR);$db=new PDO($cfg['db']['dsn'],$cfg['db']['user'],$cfg['db']['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);
 opsRate('all',100,60);
 if($action==='public'){
  if($method!=='GET')stop(405,'Método no permitido.');$p=$db->query("SELECT name,slug,twitch FROM companion_partners WHERE active=1 AND twitch<>'' ORDER BY created_at LIMIT 12")->fetchAll(PDO::FETCH_ASSOC);reply(['notices'=>opsNotices($db,'web'),'releases'=>(object)opsReleases($db),'partners'=>$p,'billingEnabled'=>billingEnabled()]);
 }
 if($action==='download'){
  if($method!=='GET')stop(405,'Método no permitido.');$id=opsId($_GET['id']??null);$q=$db->prepare('SELECT * FROM companion_releases WHERE id=? AND published=1');$q->execute([$id]);$r=$q->fetch(PDO::FETCH_ASSOC);$p=$private.'/releases/'.$id.'.exe';if(!$r||!is_file($p))stop(404,'Descarga no disponible.');
  $h=fopen($p,'rb');if(!$h)stop(503,'Archivo no disponible.');header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="'.$r['filename'].'"');header('Content-Length: '.filesize($p));header('X-Checksum-SHA256: '.$r['sha256']);header('Cache-Control: private, max-age=0');fpassthru($h);fclose($h);exit;
 }
 if(!in_array($action,['tickets','ticket','ticket-create','ticket-reply','usage','discount-check'],true))stop(400,'Acción no válida.');$write=in_array($action,['ticket-create','ticket-reply','usage','discount-check'],true);if($method!==($write?'POST':'GET'))stop(405,'Método no permitido.');
 ini_set('session.use_strict_mode','1');ini_set('session.use_only_cookies','1');ini_set('session.save_path',$private.'/sessions');session_name('__Host-aion_session');session_set_cookie_params(['path'=>'/','secure'=>true,'httponly'=>true,'samesite'=>'Lax']);session_start();
 if(!isset($_SESSION['uid'])||time()-($_SESSION['born']??0)>43200||time()-($_SESSION['last']??0)>7200)stop(401,'Inicia sesión en Daeva Companion.');$q=$db->prepare('SELECT id,auth_version,status FROM companion_users WHERE id=?');$q->execute([$_SESSION['uid']]);$u=$q->fetch(PDO::FETCH_ASSOC);if(!$u||$u['status']!=='active'||(int)$u['auth_version']!==($_SESSION['auth_version']??0))stop(401,'Sesión caducada.');
 $body=[];if($write){if(($_SERVER['HTTP_ORIGIN']??'')!==$cfg['origin']||!hash_equals($_SESSION['csrf']??'',(string)($_SERVER['HTTP_X_CSRF_TOKEN']??'')))stop(403,'Origen o sesión no válido.');if(!str_starts_with(strtolower($_SERVER['CONTENT_TYPE']??''),'application/json'))stop(415,'Se requiere JSON.');$raw=file_get_contents('php://input',false,null,0,16385);if(strlen($raw)>16384)stop(413,'Solicitud demasiado grande.');try{$body=json_decode($raw,true,16,JSON_THROW_ON_ERROR);}catch(Throwable){stop(400,'JSON no válido.');}if(!is_array($body)||array_is_list($body))stop(400,'Solicitud no válida.');}
 $_SESSION['last']=time();session_write_close();$uid=$u['id'];
 if($action==='usage'){$feature=opsEnum($body['feature']??null,['home','overview','equipment','daevanion','roadmap','map','skills','progress','database','damage','events','ranking','profile','desktop']);opsRate('usage'.$uid,30,60);opsUsage($db,$uid,$feature);reply(['saved'=>true]);}
 if($action==='discount-check'){
  opsRate('discount'.$uid,10,300);$code=strtoupper(opsText($body['code']??null,3,40));$q=$db->prepare('SELECT code,percent FROM companion_discounts WHERE code=? AND active=1 AND starts_at<=UTC_TIMESTAMP() AND ends_at>UTC_TIMESTAMP() AND (max_uses IS NULL OR uses<max_uses)');$q->execute([$code]);$d=$q->fetch(PDO::FETCH_ASSOC);reply(['valid'=>(bool)$d,'discount'=>$d?['code'=>$d['code'],'percent'=>(int)$d['percent']]:null,'billingEnabled'=>billingEnabled(),'redeemed'=>false,'message'=>$d?'Código válido. Se aplica al mes que contrates; revisa el importe antes de pagar. No se ha canjeado todavía.':'Código no disponible.']);
 }
 if($action==='tickets'){$q=$db->prepare('SELECT id,subject,category,status,priority,created_at,updated_at FROM companion_tickets WHERE user_id=? ORDER BY updated_at DESC LIMIT 100');$q->execute([$uid]);reply(['tickets'=>$q->fetchAll(PDO::FETCH_ASSOC)]);}
 if($action==='ticket'){
  $id=opsId($_GET['id']??null);$q=$db->prepare('SELECT id,subject,category,status,priority,created_at,updated_at FROM companion_tickets WHERE id=? AND user_id=?');$q->execute([$id,$uid]);$t=$q->fetch(PDO::FETCH_ASSOC);if(!$t)stop(404,'Consulta no encontrada.');$q=$db->prepare('SELECT m.body,m.created_at,u.username FROM companion_ticket_messages m JOIN companion_users u ON u.id=m.author_id WHERE m.ticket_id=? AND m.internal=0 ORDER BY m.id LIMIT 200');$q->execute([$id]);$t['messages']=$q->fetchAll(PDO::FETCH_ASSOC);reply(['ticket'=>$t]);
 }
 opsRate('ticket'.$uid,10,3600);$message=opsText($body['message']??null,5,5000);$db->beginTransaction();
 if($action==='ticket-create'){
  $subject=opsText($body['subject']??null,5,160);$category=opsEnum($body['category']??null,['account','desktop','map','data','subscription','other']);$id=bin2hex(random_bytes(16));$device=$body['deviceId']??null;if($device){$device=opsId($device);$entry=json_decode(@file_get_contents($private.'/companion/device-'.$device.'.json')?:'null',true);if(($entry['userId']??null)!==$uid)stop(400,'Dispositivo no válido para esta cuenta.');}else $device=null;
  $character=null;if(isset($body['character'])){$c=$body['character'];if(!is_array($c)||!in_array($c['region']??'',['la','eu','nae','naw','as'],true)||!preg_match('/^\d{4,5}$/D',(string)($c['serverId']??''))||!preg_match('/^[A-Za-z0-9_=-]{10,120}$/D',(string)($c['characterId']??'')))stop(400,'Personaje no válido.');$ref=['region'=>$c['region'],'serverId'=>(int)$c['serverId'],'characterId'=>$c['characterId']];$link=json_decode(@file_get_contents($private.'/companion/link-'.hash('sha256',json_encode($ref)).'.json')?:'null',true);$owned=($link['userId']??null)===$uid;$character=json_encode(['region'=>$c['region'],'serverId'=>(int)$c['serverId'],'characterId'=>$c['characterId'],'ownershipVerified'=>$owned]);}
  $q=$db->prepare('INSERT INTO companion_tickets(id,user_id,subject,category,device_id,character_json,created_at,updated_at) VALUES (?,?,?,?,?,?,UTC_TIMESTAMP(),UTC_TIMESTAMP())');$q->execute([$id,$uid,$subject,$category,$device,$character]);
 }else{
  $id=opsId($body['id']??null);$q=$db->prepare('SELECT id,status FROM companion_tickets WHERE id=? AND user_id=? FOR UPDATE');$q->execute([$id,$uid]);$t=$q->fetch(PDO::FETCH_ASSOC);if(!$t)stop(404,'Consulta no encontrada.');if($t['status']==='closed')stop(409,'Esta consulta está cerrada. Crea una nueva si necesitas ayuda.');$q=$db->prepare("UPDATE companion_tickets SET status='open',updated_at=UTC_TIMESTAMP() WHERE id=?");$q->execute([$id]);
 }
 $q=$db->prepare('SELECT COUNT(*) FROM companion_ticket_messages WHERE ticket_id=?');$q->execute([$id]);if((int)$q->fetchColumn()>=200)stop(409,'Límite de mensajes alcanzado. Crea una nueva consulta.');$q=$db->prepare('INSERT INTO companion_ticket_messages(ticket_id,author_id,body,internal,created_at) VALUES (?,?,?,0,UTC_TIMESTAMP())');$q->execute([$id,$uid,$message]);$db->commit();reply(['id'=>$id,'message'=>'Consulta enviada. Puedes seguirla desde esta página.']);
}catch(Throwable $e){if(isset($db)&&$db->inTransaction())$db->rollBack();error_log('Daeva operations: '.$e->getCode());stop(503,'Servicio temporalmente no disponible.');}
